CREATE OR REPLACE FUNCTION activities.pr_potential_v2(p_weight_delta numeric, p_vo2_max_delta numeric, p_acute_load_delta numeric, p_max_load_delta numeric, p_distance_mi numeric, p_elevation_gain_m numeric, p_reference_time_s numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    v_elev_ratio   NUMERIC;
    v_pr_score     NUMERIC;
BEGIN
    -- Guard: avoid division by zero on degenerate course data
    IF p_distance_mi IS NULL OR p_distance_mi <= 0 THEN
        RAISE EXCEPTION 'p_distance_mi must be a positive non-null value';
    END IF;

    IF p_reference_time_s IS NULL OR p_reference_time_s <= 0 THEN
        RAISE EXCEPTION 'p_reference_time_s must be a positive non-null value';
    END IF;

    -- Elevation ratio determines which regime applies
    -- Threshold of 6 m/mi derived from median elev ratio in calibration dataset
    v_elev_ratio := COALESCE(p_elevation_gain_m, 0) / p_distance_mi;

    IF v_elev_ratio < 6 THEN
        -- Flat / low-gradient regime
        -- VO2 and max_load are excluded: both were statistically insignificant
        -- on flat courses in the calibration data (VO2 p=0.16, max_load p=0.04
        -- but with a counterintuitive sign consistent with collinearity artifact)
        v_pr_score :=
                0.80 * COALESCE(p_weight_delta, 0)
                    + 0.021 * COALESCE(p_acute_load_delta, 0);
    ELSE
        -- Hilly / steep regime
        -- Acute load excluded: not significant on steep courses (p=0.42)
        v_pr_score :=
                0.47  * COALESCE(p_weight_delta, 0)
                    - 0.83  * COALESCE(p_vo2_max_delta, 0)
                    - 0.015 * COALESCE(p_max_load_delta, 0);
    END IF;

    -- PR_Score is the predicted fractional time delta vs reference.
    -- Negative score → faster than PR; positive → slower than PR.
    RETURN ROUND((p_reference_time_s * (1.0 + v_pr_score))::NUMERIC, 2);
END;
$function$

CREATE OR REPLACE FUNCTION activities.pr_potential_v3(weight_delta_pct double precision, vo2_delta_pct double precision, acute_load_delta double precision, distance_mi double precision, elevation_gain_m double precision, reference_time_s double precision)
 RETURNS double precision
 LANGUAGE plpgsql
AS $function$
DECLARE
    -- Core model coefficients (from regression)
    v_weight_coeff CONSTANT DOUBLE PRECISION := 0.54;
    v_vo2_coeff    CONSTANT DOUBLE PRECISION := -1.04;
    v_acute_coeff  CONSTANT DOUBLE PRECISION := 0.01;

    -- Derived values
    v_base_delta DOUBLE PRECISION;
    v_grade_factor DOUBLE PRECISION;
    v_adjusted_delta DOUBLE PRECISION;
BEGIN
    /*
        Base predicted % delta vs reference

        Interpretation:
        - Positive = slower than reference
        - Negative = faster than reference
    */
    v_base_delta :=
          (v_weight_coeff * COALESCE(weight_delta_pct,0))
        + (v_vo2_coeff    * COALESCE(vo2_delta_pct,0))
        + (v_acute_coeff  * COALESCE(acute_load_delta,0));

    /*
        Optional course adjustment (kept intentionally small and stable)

        Rationale:
        - Elevation impact scales roughly with grade (elevation per mile)
        - Weight matters slightly more on steeper courses
        - VO2 matters slightly more on longer efforts

        This is a *light-touch modifier*, not a re-fit model.
    */
    IF distance_mi > 0 THEN
        v_grade_factor := elevation_gain_m / distance_mi;
    ELSE
        v_grade_factor := 0;
    END IF;

    /*
        Apply small interaction adjustments:
        - Increase weight penalty slightly for steeper courses
        - Increase VO2 benefit slightly for longer courses
    */
    v_adjusted_delta :=
        v_base_delta
        * (
            1
            + (0.0005 * v_grade_factor)   -- hill sensitivity
            + (0.02   * LN(GREATEST(distance_mi, 1)))
          );

    /*
        Final predicted time
    */
    RETURN round((reference_time_s * (1 + v_adjusted_delta))::NUMERIC,2);

END;
$function$

CREATE OR REPLACE PROCEDURE activities.rebuild_elevation_reference()
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    TRUNCATE activities.elevation_reference;
    ANALYZE activities.activity_details_distance;

    INSERT INTO activities.elevation_reference (grid_5m_00_id, avg_elevation, obs_count, elev_stddev)
    SELECT
        grid_5m_00_id,
        percentile_disc(0.5) WITHIN GROUP (
            ORDER BY elevation_m_smooth
        ) as avg_elevation,
        count(*) as obs_count,
        stddev(elevation_m_smooth) as elev_stddev
    FROM activities.activity_details_distance
    GROUP BY grid_5m_00_id;

    UPDATE activities.elevation_reference
    SET elevation_hammered = avg_elevation;

END;
$procedure$

CREATE OR REPLACE PROCEDURE activities.smooth_elevation_spikes_by_distance(IN p_activity_id bigint DEFAULT NULL::bigint)
 LANGUAGE plpgsql
AS $procedure$
DECLARE
    v_is_loop BOOLEAN;
    v_start_elev FLOAT;
    v_start_elev_reference FLOAT;
    v_end_elev FLOAT;
    v_end_elev_reference FLOAT;
    v_drift_per_meter FLOAT;
    v_drift_per_meter_reference FLOAT;
    v_total_distance FLOAT;
BEGIN
    -- 1. Create a temporary work table for this activity to keep I/O sequential
    DROP TABLE if exists current_track;

    CREATE TEMP TABLE current_track AS
    SELECT
        activity_id as id,
        distance_m,
        elevation_m,
        elevation_reference,
        loc_point as geom,
        -- STEP A: Rolling Median (Window of 10 meters)
        -- We use a subquery/array approach because percentile_cont isn't a native window function
        (SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY sub.elevation_m)
         FROM (
                  SELECT t2.elevation_m
                  FROM activities.activity_details_distance t2
                  WHERE t2.activity_id = p_activity_id
                    AND t2.distance_m BETWEEN t1.distance_m - 10 AND t1.distance_m + 10
              ) sub) as smoothed_elev,
        (SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY sub.elevation_reference)
         FROM (
                  SELECT t2.elevation_reference
                  FROM activities.activity_details_distance t2
                  WHERE t2.activity_id = p_activity_id
                    AND t2.distance_m BETWEEN t1.distance_m - 10 AND t1.distance_m + 10
              ) sub) as smoothed_elev_reference
    FROM activities.activity_details_distance t1
    WHERE activity_id = p_activity_id
    ORDER BY distance_m;

    -- 2. Detect if it's a loop (Start/End within 20m of each other)
    SELECT
        ST_Distance(
                (SELECT geom FROM current_track ORDER BY distance_m ASC LIMIT 1),
                (SELECT geom FROM current_track ORDER BY distance_m DESC LIMIT 1)
        ) < 100 INTO v_is_loop;

    -- 3. If it's a loop, calculate the drift correction
    IF v_is_loop THEN
        SELECT smoothed_elev INTO v_start_elev FROM current_track ORDER BY distance_m ASC LIMIT 1;
        SELECT smoothed_elev INTO v_end_elev FROM current_track ORDER BY distance_m DESC LIMIT 1;
        SELECT smoothed_elev_reference INTO v_start_elev_reference FROM current_track ORDER BY distance_m ASC LIMIT 1;
        SELECT smoothed_elev_reference INTO v_end_elev_reference FROM current_track ORDER BY distance_m DESC LIMIT 1;
        SELECT MAX(distance_m) INTO v_total_distance FROM current_track;

        -- Total drift divided by time
        v_drift_per_meter := (v_end_elev - v_start_elev) / NULLIF(v_total_distance, 0);
        v_drift_per_meter_reference := (v_end_elev_reference - v_start_elev_reference) / NULLIF(v_total_distance, 0);
        --         SELECT
--             ((SELECT smoothed_elev FROM current_track ORDER BY elapsed_duration_s DESC LIMIT 1)
--                 - (SELECT smoothed_elev FROM current_track ORDER BY elapsed_duration_s ASC LIMIT 1))
--             / (SELECT MAX(elapsed_duration_s) FROM current_track)
    ELSE
        v_drift_per_meter := 0;
        v_drift_per_meter_reference := 0;
    END IF;

    -- 4. Update the main table with the Noise-Removed + Drift-Corrected values
    UPDATE activities.activity_details_distance t
    SET elevation_m_smooth = ROUND((ct.smoothed_elev - (ct.distance_m * v_drift_per_meter
        ))::numeric, 2),
        elevation_reference = ROUND((ct.smoothed_elev_reference - (ct.distance_m * v_drift_per_meter_reference
            ))::numeric, 2)
    FROM current_track ct
    WHERE t.activity_id = ct.id and ct.distance_m = t.distance_m;

    DROP TABLE current_track;
END;
$procedure$

CREATE OR REPLACE PROCEDURE activities.smooth_elevation_spikes_by_time(IN p_activity_id bigint DEFAULT NULL::bigint)
 LANGUAGE plpgsql
AS $procedure$
DECLARE
    v_is_loop BOOLEAN;
    v_start_elev FLOAT;
    v_end_elev FLOAT;
    v_drift_per_s FLOAT;
    v_total_time FLOAT;
BEGIN
    -- 1. Create a temporary work table for this activity to keep I/O sequential
    DROP TABLE if exists current_track;

    CREATE TEMP TABLE current_track AS
    SELECT
        activity_id as id,
        elapsed_duration_s,
        elevation_m,
        loc_point as geom,
        -- STEP A: Rolling Median (Window of 10 meters)
        -- We use a subquery/array approach because percentile_cont isn't a native window function
        (SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY sub.elevation_m)
         FROM (
                  SELECT t2.elevation_m
                  FROM activities.activity_details t2
                  WHERE t2.activity_id = p_activity_id
                    AND t2.elapsed_duration_s BETWEEN t1.elapsed_duration_s - 10 AND t1.elapsed_duration_s + 10
              ) sub) as smoothed_elev
    FROM activities.activity_details t1
    WHERE activity_id = p_activity_id
    ORDER BY elapsed_duration_s;

    -- 2. Detect if it's a loop (Start/End within 20m of each other)
    SELECT
        ST_Distance(
                (SELECT geom FROM current_track ORDER BY elapsed_duration_s ASC LIMIT 1),
                (SELECT geom FROM current_track ORDER BY elapsed_duration_s DESC LIMIT 1)
        ) < 100 INTO v_is_loop;

    -- 3. If it's a loop, calculate the drift correction
    IF v_is_loop THEN
        SELECT smoothed_elev INTO v_start_elev FROM current_track ORDER BY elapsed_duration_s ASC LIMIT 1;
        SELECT smoothed_elev INTO v_end_elev FROM current_track ORDER BY elapsed_duration_s DESC LIMIT 1;
        SELECT MAX(elapsed_duration_s) INTO v_total_time FROM current_track;

        -- Total drift divided by time
        v_drift_per_s := (v_end_elev - v_start_elev) / NULLIF(v_total_time, 0);
--         SELECT
--             ((SELECT smoothed_elev FROM current_track ORDER BY elapsed_duration_s DESC LIMIT 1)
--                 - (SELECT smoothed_elev FROM current_track ORDER BY elapsed_duration_s ASC LIMIT 1))
--             / (SELECT MAX(elapsed_duration_s) FROM current_track)
    ELSE
        v_drift_per_s:= 0;
    END IF;

    -- 4. Update the main table with the Noise-Removed + Drift-Corrected values
    UPDATE activities.activity_details t
    SET elevation_m_smooth = ROUND((ct.smoothed_elev - (ct.elapsed_duration_s * v_drift_per_s
     ))::numeric, 2)
    FROM current_track ct
    WHERE t.activity_id = ct.id and ct.elapsed_duration_s = t.elapsed_duration_s;

    DROP TABLE current_track;
END;
$procedure$

CREATE OR REPLACE PROCEDURE activities.update_elevations_for_activity(IN p_activity_id bigint)
 LANGUAGE plpgsql
AS $procedure$
DECLARE
    v_rows_updated INT;
BEGIN
    RAISE NOTICE 'Updating elevations for activity %...', p_activity_id;

    UPDATE activities.activity_details ad
    SET elevation_tiles = ST_Value(
        et.rast, 
        ST_SetSRID(ST_MakePoint(ad.longitude, ad.latitude), 4326)
    )
    FROM activities.elevation_tiles et
    WHERE ad.activity_id = p_activity_id
      AND et.tile_id = activities.get_tile_id(ad.latitude, ad.longitude)
      AND ad.elevation_tiles IS NULL
      AND ST_Intersects(et.rast, ST_SetSRID(ST_MakePoint(ad.longitude, ad.latitude), 4326));

    GET DIAGNOSTICS v_rows_updated = ROW_COUNT;

    RAISE NOTICE 'Updated % points for activity %', v_rows_updated, p_activity_id;
END;
$procedure$

CREATE OR REPLACE FUNCTION public.__st_countagg_transfn(agg agg_count, rast raster, nband integer DEFAULT 1, exclude_nodata_value boolean DEFAULT true, sample_percent double precision DEFAULT 1)
 RETURNS agg_count
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
	DECLARE
		_count bigint;
		rtn_agg agg_count;
	BEGIN

		-- only process parameter args once
		IF agg IS NULL THEN
			rtn_agg.count := 0;

			IF nband < 1 THEN
				RAISE EXCEPTION 'Band index must be greater than zero (1-based)';
			ELSE
				rtn_agg.nband := nband;
			END IF;

			IF exclude_nodata_value IS FALSE THEN
				rtn_agg.exclude_nodata_value := FALSE;
			ELSE
				rtn_agg.exclude_nodata_value := TRUE;
			END IF;

			IF sample_percent < 0. OR sample_percent > 1. THEN
				RAISE EXCEPTION 'Sample percent must be between zero and one';
			ELSE
				rtn_agg.sample_percent := sample_percent;
			END IF;
		ELSE
			rtn_agg := agg;
		END IF;

		IF rast IS NOT NULL THEN
			IF rtn_agg.exclude_nodata_value IS FALSE THEN
				SELECT width * height INTO _count FROM public.ST_Metadata(rast);
			ELSE
				SELECT count INTO _count FROM public._ST_summarystats(
					rast,
				 	rtn_agg.nband, rtn_agg.exclude_nodata_value,
					rtn_agg.sample_percent
				);
			END IF;
		END IF;

		rtn_agg.count := rtn_agg.count + _count;
		RETURN rtn_agg;
	END;
	$function$

CREATE OR REPLACE FUNCTION public._add_overview_constraint(ovschema name, ovtable name, ovcolumn name, refschema name, reftable name, refcolumn name, factor integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STRICT
AS $function$
	DECLARE
		fqtn text;
		cn name;
		sql text;
	BEGIN
		fqtn := '';
		IF length($1) > 0 THEN
			fqtn := quote_ident($1) || '.';
		END IF;
		fqtn := fqtn || quote_ident($2);

		cn := 'enforce_overview_' || $3;

		sql := 'ALTER TABLE ' || fqtn
			|| ' ADD CONSTRAINT ' || quote_ident(cn)
			|| ' CHECK ( public._overview_constraint(' || quote_ident($3)
			|| ',' || $7
			|| ',' || quote_literal($4)
			|| ',' || quote_literal($5)
			|| ',' || quote_literal($6)
			|| '))';

		RETURN  public._add_raster_constraint(cn, sql);
	END;
	$function$

CREATE OR REPLACE FUNCTION public._add_raster_constraint(cn name, sql text)
 RETURNS boolean
 LANGUAGE plpgsql
 STRICT
AS $function$
	BEGIN
		BEGIN
			EXECUTE sql;
		EXCEPTION
			WHEN duplicate_object THEN
				RAISE NOTICE 'The constraint "%" already exists.  To replace the existing constraint, delete the constraint and call ApplyRasterConstraints again', cn;
			WHEN OTHERS THEN
				RAISE NOTICE 'Unable to add constraint: %', cn;
				RAISE NOTICE 'SQL used for failed constraint: %', sql;
				RAISE NOTICE 'Returned error message: % (%)', SQLERRM, SQLSTATE;
				RETURN FALSE;
		END;

		RETURN TRUE;
	END;
	$function$

CREATE OR REPLACE FUNCTION public._add_raster_constraint_alignment(rastschema name, rasttable name, rastcolumn name)
 RETURNS boolean
 LANGUAGE plpgsql
 STRICT
AS $function$
	DECLARE
		fqtn text;
		cn name;
		sql text;
		attr text;
	BEGIN
		fqtn := '';
		IF length($1) > 0 THEN
			fqtn := quote_ident($1) || '.';
		END IF;
		fqtn := fqtn || quote_ident($2);

		cn := 'enforce_same_alignment_' || $3;

		sql := 'SELECT public.st_makeemptyraster(1, 1, upperleftx, upperlefty, scalex, scaley, skewx, skewy, srid) FROM public.st_metadata((SELECT '
			|| quote_ident($3)
			|| ' FROM '
			|| fqtn
			|| ' WHERE '
			|| quote_ident($3)
			|| ' IS NOT NULL LIMIT 1))';
		BEGIN
			EXECUTE sql INTO attr;
		EXCEPTION WHEN OTHERS THEN
			RAISE NOTICE 'Unable to get the alignment of a sample raster: % (%)',
        SQLERRM, SQLSTATE;
			RETURN FALSE;
		END;

		sql := 'ALTER TABLE ' || fqtn ||
			' ADD CONSTRAINT ' || quote_ident(cn) ||
			' CHECK (public.st_samealignment(' || quote_ident($3) || ', ''' || attr || '''::raster))';
		RETURN  public._add_raster_constraint(cn, sql);
	END;
	$function$

CREATE OR REPLACE FUNCTION public._add_raster_constraint_blocksize(rastschema name, rasttable name, rastcolumn name, axis text)
 RETURNS boolean
 LANGUAGE plpgsql
 STRICT
AS $function$
	DECLARE
		fqtn text;
		cn name;
		sql text;
		attrset integer[];
		attr integer;
	BEGIN
		IF lower($4) != 'width' AND lower($4) != 'height' THEN
			RAISE EXCEPTION 'axis must be either "width" or "height"';
			RETURN FALSE;
		END IF;

		fqtn := '';
		IF length($1) > 0 THEN
			fqtn := quote_ident($1) || '.';
		END IF;
		fqtn := fqtn || quote_ident($2);

		cn := 'enforce_' || $4 || '_' || $3;

		sql := 'SELECT public.st_' || $4 || '('
			|| quote_ident($3)
			|| ') FROM ' || fqtn
			|| ' GROUP BY 1 ORDER BY count(*) DESC';
		BEGIN
			attrset := ARRAY[]::integer[];
			FOR attr IN EXECUTE sql LOOP
				attrset := attrset || attr;
			END LOOP;
		EXCEPTION WHEN OTHERS THEN
			RAISE NOTICE 'Unable to get the % of a sample raster: % (%)',
        $4, SQLERRM, SQLSTATE;
			RETURN FALSE;
		END;

		sql := 'ALTER TABLE ' || fqtn
			|| ' ADD CONSTRAINT ' || quote_ident(cn)
			|| ' CHECK (st_' || $4 || '('
			|| quote_ident($3)
			|| ') IN (' || array_to_string(attrset, ',') || '))';
		RETURN  public._add_raster_constraint(cn, sql);
	END;
	$function$

CREATE OR REPLACE FUNCTION public._add_raster_constraint_coverage_tile(rastschema name, rasttable name, rastcolumn name)
 RETURNS boolean
 LANGUAGE plpgsql
 STRICT
AS $function$
	DECLARE
		fqtn text;
		cn name;
		sql text;

		_scalex double precision;
		_scaley double precision;
		_skewx double precision;
		_skewy double precision;
		_tilewidth integer;
		_tileheight integer;
		_alignment boolean;

		_covextent public.geometry;
		_covrast public.raster;
	BEGIN
		fqtn := '';
		IF length($1) > 0 THEN
			fqtn := quote_ident($1) || '.';
		END IF;
		fqtn := fqtn || quote_ident($2);

		cn := 'enforce_coverage_tile_' || $3;

		-- metadata
		BEGIN
			sql := 'WITH foo AS (SELECT public.ST_Metadata(' || quote_ident($3) || ') AS meta, public.ST_ConvexHull(' || quote_ident($3) || ') AS hull FROM ' || fqtn || ') SELECT max((meta).scalex), max((meta).scaley), max((meta).skewx), max((meta).skewy), max((meta).width), max((meta).height), public.ST_Union(hull) FROM foo';
			EXECUTE sql INTO _scalex, _scaley, _skewx, _skewy, _tilewidth, _tileheight, _covextent;
		EXCEPTION WHEN OTHERS THEN
			RAISE DEBUG 'Unable to get coverage metadata for %.%: % (%)',
        fqtn, quote_ident($3), SQLERRM, SQLSTATE;
      -- TODO: Why not return false here ?
		END;

		-- rasterize extent
		BEGIN
			_covrast := public.ST_AsRaster(_covextent, _scalex, _scaley, '8BUI', 1, 0, NULL, NULL, _skewx, _skewy);
			IF _covrast IS NULL THEN
				RAISE NOTICE 'Unable to create coverage raster: ST_AsRaster returned NULL.';
				RETURN FALSE;
			END IF;

			-- remove band
			_covrast := ST_MakeEmptyRaster(_covrast);
		EXCEPTION WHEN OTHERS THEN
			RAISE NOTICE 'Unable to create coverage raster. Cannot add coverage tile constraint: % (%)',
        SQLERRM, SQLSTATE;
			RETURN FALSE;
		END;

		sql := 'ALTER TABLE ' || fqtn ||
			' ADD CONSTRAINT ' || quote_ident(cn) ||
			' CHECK (public.st_iscoveragetile(' || quote_ident($3) || ', ''' || _covrast || '''::raster, ' || _tilewidth || ', ' || _tileheight || '))';
		RETURN  public._add_raster_constraint(cn, sql);
	END;
	$function$

CREATE OR REPLACE FUNCTION public._add_raster_constraint_extent(rastschema name, rasttable name, rastcolumn name)
 RETURNS boolean
 LANGUAGE plpgsql
 STRICT COST 9000
AS $function$
	DECLARE
		fqtn text;
		cn name;
		sql text;
		attr text; srid integer;
	BEGIN
		fqtn := '';
		IF length(rastschema) > 0 THEN
			fqtn := quote_ident(rastschema) || '.';
		END IF;
		fqtn := fqtn || quote_ident(rasttable);

		sql := 'SELECT public.ST_SRID('
			|| quote_ident(rastcolumn)
			|| ') FROM '
			|| fqtn
			|| ' WHERE '
			|| quote_ident(rastcolumn)
			|| ' IS NOT NULL LIMIT 1;';
                EXECUTE sql INTO srid;

    IF srid IS NULL THEN
      RETURN false;
    END IF;

		cn := 'enforce_max_extent_' || rastcolumn;

		sql := 'SELECT public.st_ashexewkb( public.st_setsrid( public.st_extent( public.st_envelope('
			|| quote_ident(rastcolumn)
			|| ')), ' || srid || ')) FROM '
			|| fqtn;
		EXECUTE sql INTO attr;

		-- NOTE: I put NOT VALID to prevent the costly step of validating the constraint
		sql := 'ALTER TABLE ' || fqtn
			|| ' ADD CONSTRAINT ' || quote_ident(cn)
			|| ' CHECK ( public.st_envelope('
			|| quote_ident(rastcolumn)
			|| ') @ ''' || attr || '''::geometry) NOT VALID';
		RETURN  public._add_raster_constraint(cn, sql);
	END;
	$function$

CREATE OR REPLACE FUNCTION public._add_raster_constraint_nodata_values(rastschema name, rasttable name, rastcolumn name)
 RETURNS boolean
 LANGUAGE plpgsql
 STRICT
AS $function$
	DECLARE
		fqtn text;
		cn name;
		sql text;
		attr numeric[];
		max int;
	BEGIN
		fqtn := '';
		IF length($1) > 0 THEN
			fqtn := quote_ident($1) || '.';
		END IF;
		fqtn := fqtn || quote_ident($2);

		cn := 'enforce_nodata_values_' || $3;

		sql := 'SELECT public._raster_constraint_nodata_values(' || quote_ident($3)
			|| ') FROM ' || fqtn
			|| ' WHERE '
			|| quote_ident($3)
			|| ' IS NOT NULL LIMIT 1;';
		BEGIN
			EXECUTE sql INTO attr;
		EXCEPTION WHEN OTHERS THEN
			RAISE NOTICE 'Unable to get the nodata values of a sample raster: % (%)',
        SQLERRM, SQLSTATE;
			RETURN FALSE;
		END;
		max := array_length(attr, 1);
		IF max < 1 OR max IS NULL THEN
			RAISE NOTICE 'Unable to get the nodata values of a sample raster (max < 1 or null)';
			RETURN FALSE;
		END IF;

		sql := 'ALTER TABLE ' || fqtn
			|| ' ADD CONSTRAINT ' || quote_ident(cn)
			|| ' CHECK (public._raster_constraint_nodata_values(' || quote_ident($3)
			|| ')::numeric[] = ''{';
		FOR x in 1..max LOOP
			IF attr[x] IS NULL THEN
				sql := sql || 'NULL';
			ELSE
				sql := sql || attr[x];
			END IF;
			IF x < max THEN
				sql := sql || ',';
			END IF;
		END LOOP;
		sql := sql || '}''::numeric[])';

		RETURN  public._add_raster_constraint(cn, sql);
	END;
	$function$

CREATE OR REPLACE FUNCTION public._add_raster_constraint_num_bands(rastschema name, rasttable name, rastcolumn name)
 RETURNS boolean
 LANGUAGE plpgsql
 STRICT
AS $function$
	DECLARE
		fqtn text;
		cn name;
		sql text;
		attr int;
	BEGIN
		fqtn := '';
		IF length($1) > 0 THEN
			fqtn := quote_ident($1) || '.';
		END IF;
		fqtn := fqtn || quote_ident($2);

		cn := 'enforce_num_bands_' || $3;

		sql := 'SELECT public.st_numbands(' || quote_ident($3)
			|| ') FROM '
			|| fqtn
			|| ' WHERE '
			|| quote_ident($3)
			|| ' IS NOT NULL LIMIT 1;';
		BEGIN
			EXECUTE sql INTO attr;
		EXCEPTION WHEN OTHERS THEN
			RAISE NOTICE 'Unable to get the number of bands of a sample raster: % (%)',
        SQLERRM, SQLSTATE;
			RETURN FALSE;
		END;

		sql := 'ALTER TABLE ' || fqtn
			|| ' ADD CONSTRAINT ' || quote_ident(cn)
			|| ' CHECK (public.st_numbands(' || quote_ident($3)
			|| ') = ' || attr
			|| ')';
		RETURN  public._add_raster_constraint(cn, sql);
	END;
	$function$

CREATE OR REPLACE FUNCTION public._add_raster_constraint_out_db(rastschema name, rasttable name, rastcolumn name)
 RETURNS boolean
 LANGUAGE plpgsql
 STRICT
AS $function$
	DECLARE
		fqtn text;
		cn name;
		sql text;
		attr boolean[];
		max int;
	BEGIN
		fqtn := '';
		IF length($1) > 0 THEN
			fqtn := quote_ident($1) || '.';
		END IF;
		fqtn := fqtn || quote_ident($2);

		cn := 'enforce_out_db_' || $3;

		sql := 'SELECT public._raster_constraint_out_db(' || quote_ident($3)
			|| ') FROM ' || fqtn
			|| ' WHERE '
			|| quote_ident($3)
			|| ' IS NOT NULL LIMIT 1;';
		BEGIN
			EXECUTE sql INTO attr;
		EXCEPTION WHEN OTHERS THEN
			RAISE NOTICE 'Unable to get the out-of-database bands of a sample raster: % (%)',
        SQLERRM, SQLSTATE;
			RETURN FALSE;
		END;
		max := array_length(attr, 1);
		IF max < 1 OR max IS NULL THEN
			RAISE NOTICE 'Unable to get the out-of-database bands of a sample raster (max < 1 or null)';
			RETURN FALSE;
		END IF;

		sql := 'ALTER TABLE ' || fqtn
			|| ' ADD CONSTRAINT ' || quote_ident(cn)
			|| ' CHECK ( public._raster_constraint_out_db(' || quote_ident($3)
			|| ') = ''{';
		FOR x in 1..max LOOP
			IF attr[x] IS FALSE THEN
				sql := sql || 'FALSE';
			ELSE
				sql := sql || 'TRUE';
			END IF;
			IF x < max THEN
				sql := sql || ',';
			END IF;
		END LOOP;
		sql := sql || '}''::boolean[])';

		RETURN  public._add_raster_constraint(cn, sql);
	END;
	$function$

